//////////////////////////////////////////////////////////////////////////////////////////////////
// Icon artwork, embedded the same way Dashboard.h embeds the HTML: base64 text baked into the
// binary as a raw string literal, decoded once into a function-local static on first use. Same
// reasoning as Dashboard.h - no asset directory, nothing read from disk at runtime.
//
// Source art: H:\Alex\Images\Creative\misc\Loom_Icon_128x128.png (favicon / header mark) and
// Loom_Icon.png, 512x512 (About panel). Regenerate these blobs from the source PNGs if the art
// changes - do not hand-edit the base64 text.
//////////////////////////////////////////////////////////////////////////////////////////////////

#include <array>
#include <string>
#include <vector>

namespace loom_icon_detail
{
    //----------------------------------------------------------------------------------------
    // Minimal base64 decoder. Skips anything outside the alphabet (the line-wrapping newlines
    // below, in particular) rather than treating it as an error - there is no untrusted input
    // here, just our own generated text.
    //----------------------------------------------------------------------------------------
    inline std::vector<unsigned char> DecodeBase64(const std::string& in)
    {
        static const std::array<int, 256> table = []
        {
            std::array<int, 256> t;
            t.fill(-1);
            const char* alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
            for (int i = 0; i < 64; ++i)
                t[static_cast<unsigned char>(alphabet[i])] = i;
            return t;
        }();

        std::vector<unsigned char> out;
        out.reserve(in.size() / 4 * 3);

        int val = 0, bits = -8;
        for (unsigned char c : in)
        {
            if (c == '=') break;
            const int d = table[c];
            if (d == -1) continue;
            val = (val << 6) + d;
            bits += 6;
            if (bits >= 0)
            {
                out.push_back(static_cast<unsigned char>((val >> bits) & 0xFF));
                bits -= 8;
            }
        }
        return out;
    }
}

